import React from 'react';

/** Visual variant for the TypingIndicator. */
export type TypingIndicatorVariant = 'ascii' | 'dither';

/** Size preset for the TypingIndicator. */
export type TypingIndicatorSize = 'compact';

/** Props for the {@link TypingIndicator} component. */
export interface TypingIndicatorProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Visual variant. */
  variant?: TypingIndicatorVariant;
  /** Size preset. */
  size?: TypingIndicatorSize;
  /** Optional text label (e.g. "typing..."). */
  text?: string;
  /** Additional CSS class names. */
  className?: string;
}

/**
 * Animated typing/thinking indicator for AI chat interfaces.
 * Renders three bouncing dots (or ASCII block characters in the `ascii` variant).
 */
export const TypingIndicator = React.forwardRef<HTMLDivElement, TypingIndicatorProps>(
  ({ variant, size, text, className, ...rest }, ref) => (
    <div
      ref={ref}
      className={`sk-typing-indicator${className ? ` ${className}` : ''}`}
      data-variant={variant}
      data-size={size}
      {...rest}
    >
      <span className="sk-typing-indicator__dots">
        <span className="sk-typing-indicator__dot" />
        <span className="sk-typing-indicator__dot" />
        <span className="sk-typing-indicator__dot" />
      </span>
      {text && <span className="sk-typing-indicator__text">{text}</span>}
    </div>
  ),
);

TypingIndicator.displayName = 'TypingIndicator';

/**
 * skeehn — TypingIndicator Component
 *
 * @component sk-typing-indicator
 * @variants  default | ascii | dither
 * @sizes     default | compact
 * @states    [data-loading] | [data-skeleton]
 * @slots     __dots | __dot | __text
 * @features  3-dot bounce, ASCII block chars, dither pulse overlay
 * @a11y      aria-label for screen readers, reduced motion support
 * @print     Hidden (interactive indicator)
 */

.sk-typing-indicator {
  display: inline-flex;
  align-items: center;
  gap: var(--sk-space-2);
  padding: var(--sk-space-2) var(--sk-space-3);
  font-family: var(--sk-font-mono);
  font-size: var(--sk-font-size-xs);
  color: hsl(var(--sk-muted-foreground));
}

.sk-typing-indicator__dots {
  display: inline-flex;
  gap: 3px;
  align-items: center;
}

.sk-typing-indicator__dot {
  width: 4px;
  height: 4px;
  background: hsl(var(--sk-muted-foreground));
  border-radius: var(--sk-radius-full);
  animation: sk-typing-bounce 1.4s ease-in-out infinite;
}

.sk-typing-indicator__dot:nth-child(2) { animation-delay: 0.2s; }
.sk-typing-indicator__dot:nth-child(3) { animation-delay: 0.4s; }

@keyframes sk-typing-bounce {
  0%, 60%, 100% { transform: translateY(0); opacity: 0.4; }
  30% { transform: translateY(-4px); opacity: 1; }
}

/* ASCII variant — uses block characters instead of dots */
.sk-typing-indicator[data-variant="ascii"] .sk-typing-indicator__dots {
  font-family: var(--sk-font-mono);
  font-size: var(--sk-font-size-sm);
  gap: 1px;
}

.sk-typing-indicator[data-variant="ascii"] .sk-typing-indicator__dot {
  width: auto;
  height: auto;
  background: none;
  border-radius: 0;
  color: hsl(var(--sk-foreground));
}

.sk-typing-indicator[data-variant="ascii"] .sk-typing-indicator__dot:nth-child(1)::after { content: "░"; }
.sk-typing-indicator[data-variant="ascii"] .sk-typing-indicator__dot:nth-child(2)::after { content: "▒"; }
.sk-typing-indicator[data-variant="ascii"] .sk-typing-indicator__dot:nth-child(3)::after { content: "▓"; }

/* Dither variant — pulsing dither pattern */
.sk-typing-indicator[data-variant="dither"] {
  position: relative;
  padding: var(--sk-space-2) var(--sk-space-4);
  border: var(--sk-border);
  border-radius: var(--sk-radius);
}

.sk-typing-indicator[data-variant="dither"]::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: var(--sk-dither-pattern);
  background-repeat: repeat;
  animation: sk-dither-pulse 2s ease-in-out infinite;
  pointer-events: none;
  border-radius: inherit;
}

.sk-typing-indicator__text {
  position: relative;
  z-index: 1;
  letter-spacing: 0.02em;
}

/* Compact */
.sk-typing-indicator[data-size="compact"] {
  padding: var(--sk-space-1) var(--sk-space-2);
  gap: var(--sk-space-1);
}

.sk-typing-indicator[data-size="compact"] .sk-typing-indicator__dot {
  width: 3px;
  height: 3px;
}

/* ============================================================
   IMPROVED 3-DOT ANIMATION — pixel-stepping bounce
   ============================================================ */

@keyframes sk-typing-pixel-bounce {
  0%, 100% { transform: translateY(0); opacity: 0.3; }
  15%      { transform: translateY(-3px); opacity: 0.8; }
  30%      { transform: translateY(-5px); opacity: 1; }
  45%      { transform: translateY(-3px); opacity: 0.8; }
  60%      { transform: translateY(0); opacity: 0.5; }
}

.sk-typing-indicator[data-animation="pixel"] .sk-typing-indicator__dot {
  animation: sk-typing-pixel-bounce 1.6s steps(8) infinite;
}

.sk-typing-indicator[data-animation="pixel"] .sk-typing-indicator__dot:nth-child(2) { animation-delay: 0.15s; }
.sk-typing-indicator[data-animation="pixel"] .sk-typing-indicator__dot:nth-child(3) { animation-delay: 0.3s; }

/* ============================================================
   SKELETON
   ============================================================ */

.sk-typing-indicator[data-skeleton] {
  pointer-events: none;
}

.sk-typing-indicator[data-skeleton] .sk-typing-indicator__dots {
  background: linear-gradient(90deg, hsl(var(--sk-muted)) 25%, hsl(var(--sk-accent)) 50%, hsl(var(--sk-muted)) 75%);
  background-size: 200% 100%;
  animation: sk-card-shimmer 1.8s ease-in-out infinite;
  border-radius: var(--sk-radius);
  width: 2rem;
  height: 0.5rem;
}

.sk-typing-indicator[data-skeleton] .sk-typing-indicator__dot { display: none; }

@media print { .sk-typing-indicator { display: none; } }

@media (prefers-reduced-motion: reduce) {
  .sk-typing-indicator__dot { animation: none; opacity: 0.6; }
  .sk-typing-indicator[data-variant="dither"]::before { animation: none; opacity: 0.1; }
  .sk-typing-indicator[data-animation="pixel"] .sk-typing-indicator__dot { animation: none; opacity: 0.6; }
  .sk-typing-indicator[data-skeleton] .sk-typing-indicator__dots { animation: none; background: hsl(var(--sk-muted)); }
}
